import { buildings, eras, sources, glossary, questions } from './data.js';
import { dimensions, classification, types, functions, periodCategories, routes, recordsFor, categoryOf, categoryURL, recordURL, mainNavigation } from './catalog.js';
import { esc, icon, brandIcon, media, sourceLink, byId, eraOf } from './components.js';

export const PAGE_SIZE=6;
const paramsOf=p=>p instanceof URLSearchParams?p:new URLSearchParams(p);
const sourcesFor=list=>[...new Set(list.flatMap(b=>b.sources))];
const preview=c=>media({image:c.image,title:c.name,imageLabel:['cave','pit','fortress','apartment','neowa','city'].includes(c.image)?'설명용 개념도':''});
export function breadcrumb(items){return `<nav class="breadcrumbs" aria-label="현재 위치"><a href="/">홈</a>${items.map(([label,url])=>`<span aria-hidden="true">/</span>${url?`<a href="${url}">${esc(label)}</a>`:`<span aria-current="page">${esc(label)}</span>`}`).join('')}</nav>`;}
function intro(en,title,desc){return `<div class="page-intro"><div class="eyebrow">${en}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>`;}
export {header,sidebar} from './navigation.js';
export function footer(){return `<div class="wrap footer-main"><a class="footer-brand" href="/">${brandIcon}<strong>기억</strong><span>공간을 기록하고, 시간을 잇습니다.</span></a><div class="footer-meta"><a href="/periods/">시대별</a> · <a href="/regions/">지역별</a> · <a href="/functions/">기능별</a> · <a href="/types/">종류별</a><br>자료 확인 2026.10.26 · 원자료 ${sources.length}개 · <a href="/library/photos/">사진 출처 및 이용 안내 ↗</a></div></div>`;}
export function saveButton(b,large=false){return `<button class="${large?'button':'save-card'}" data-action="save" data-id="${b.id}" aria-label="${esc(b.title)} 보관하기" aria-pressed="false">${icon('bookmark')}${large?'<span data-save-label>보관하기</span>':''}</button>`;}
export function card(b){return `<article class="building-card" data-record-id="${b.id}"><a class="card-media" href="${recordURL(b.id)}" aria-label="${esc(b.title)} 상세 페이지">${media(b)}<span class="era-badge">${eraOf(b.era).name}</span></a>${saveButton(b)}<div class="card-body"><div class="card-meta">${icon('pin')} ${esc(b.location)}</div><a class="card-title" href="${recordURL(b.id)}">${esc(b.title)}${icon('arrow')}</a><p class="card-desc">${esc(b.summary)}</p><div class="card-bottom"><a class="small-tag" href="${categoryURL('types',classification[b.id].type)}">${categoryOf('types',classification[b.id].type).name}</a><span>${esc(b.date.split(' · ')[0])}</span></div></div></article>`;}
function cards(list){return list.map(card).join('');}
function empty(title='조건에 맞는 기록이 없습니다.',description='다른 검색어나 시대를 선택해 보세요.',url=''){return `<div class="empty">${icon('search')}<h3>${esc(title)}</h3><p>${esc(description)}</p>${url?`<a class="button" href="${url}">선택 조건 초기화 ${icon('arrow')}</a>`:''}</div>`;}
export function categoryCard(dimension,c,index=0){const count=recordsFor(dimension,c.id).length;return `<a class="category-card" href="${categoryURL(dimension,c.id)}"><div class="category-image">${preview(c)}<span class="category-count">${count}개 기록</span></div><div class="category-copy"><span class="category-order">${String(index+1).padStart(2,'0')}</span><div><h2>${esc(c.name)}</h2><span class="category-subtitle">${esc(c.subtitle||c.title||'')}</span><p>${esc(c.desc)}</p></div><span class="category-arrow">${icon('arrow')}</span></div></a>`;}
export function regionMap(){return `<svg class="map-svg" viewBox="0 0 380 445" role="group" aria-label="지역별 목록 페이지로 이동"><path class="map-land" d="m166 43 23-13 26 15 9 26 24 12 12 36 19 27 15 32 16 35 8 40-10 23 6 16-21 12-8 25-20 7-14 20-13-12-21 8-13 20-16-12-10 9-17-4-14 13-13-7-18 10-13-20 9-17-9-16 10-15-9-15 17-9-10-23 12-18-10-14 16-17-7-11 18-10-5-18 16-8-8-18 19-7-6-24 16-10-1-19 12-2Z"/><path class="map-land" d="m78 399 20-11 36 2 15 9-15 12-34 3-22-6Z"/>${dimensions.regions.categories.filter(c=>!c.supplemental).map(r=>`<a class="map-region" href="${categoryURL('regions',r.id)}" aria-label="${r.name} 건축 목록"><circle cx="${r.x}" cy="${r.y}" r="6"/><text x="${r.x+(r.id==='capital'?-14:13)}" y="${r.y+(r.id==='capital'?-14:5)}" text-anchor="${r.id==='capital'?'end':'start'}">${r.name}</text></a>`).join('')}</svg>`;}

function home(){return `<div class="wrap home-page"><section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="hero-kicker">KOREAN ARCHITECTURE ARCHIVE</div><h1 id="hero-title">공간에 담긴 시간,<br><em>나의 관점</em>으로 읽다.</h1><p>언제, 어디에, 무엇을 위해 지었을까요?<br>궁금한 유형을 고르고 한국 건축의 이야기를 따라가세요.</p><div class="hero-buttons"><a class="button primary" href="/periods/">시대별 탐색 ${icon('arrow')}</a><a class="button" href="/compare/">${icon('compare')} 두 건축 비교</a></div><div class="hero-stats"><div class="hero-stat"><strong>10</strong><span>시대의 흐름</span></div><div class="hero-stat"><strong>${types.length}</strong><span>건축의 종류</span></div><div class="hero-stat"><strong>${buildings.length}</strong><span>건축 기록</span></div></div></div><figure class="hero-visual" style="margin:0"><img class="hero-photo" src="/assets/hero.jpg" alt="광화문과 경복궁의 전각들 너머로 북악산이 보이는 풍경" width="1800" height="1200" fetchpriority="high"><div class="photo-tag"><span class="dot"></span> 조선의 공간, 이어지는 이야기</div><figcaption class="photo-caption"><span>서울 경복궁 · 광화문에서 북악산까지</span><a href="/library/photos/">사진 출처 ↗</a></figcaption></figure></section><section class="home-paths"><div class="section-head"><div><div class="eyebrow">CHOOSE YOUR PERSPECTIVE</div><h2>어떤 길로 건축을 만나볼까요?</h2><p>각 메뉴에서 유형을 선택하면, 해당 기록만 담긴 페이지로 이어집니다.</p></div><span class="directory-count">네 가지 탐색의 관점</span></div><div class="perspective-grid">${Object.entries(dimensions).map(([id,d],i)=>`<a class="perspective-card" href="/${id}/"><div class="perspective-number">0${i+1} / ${d.en}</div><div class="perspective-main"><span class="perspective-icon">${icon(d.icon)}</span><div><h3>${d.name}</h3><p>${d.question}</p></div>${icon('arrow')}</div><div class="perspective-bottom"><span>${id==='regions'?'6개 권역 + 관련 문화권':d.categories.length+'개 분류'}</span><span>${id==='periods'?'구석기 → 동시대':id==='regions'?'서울·경기 · 강원 · 제주 …':id==='functions'?'주거 · 신앙 · 문화 …':'궁궐 · 사찰 · 공동주택 …'}</span></div></a>`).join('')}</div></section><div class="home-learning"><div>${icon('book')}<span><strong>분류를 고르고, 기록을 읽고, 차이를 비교하세요.</strong><span>각 건축 상세 페이지에서 원자료와 관찰 포인트를 함께 확인할 수 있습니다.</span></span></div><a href="/library/glossary/" class="text-link">건축 용어집 ${icon('arrow')}</a></div></div>`;}

function directory(route){const d=dimensions[route.dimension];const regular=d.categories.filter(c=>!c.supplemental),extra=d.categories.filter(c=>c.supplemental);return `<div class="wrap page-content">${breadcrumb([[d.name]])}${intro(d.en,d.question,d.description)}${route.dimension==='regions'?`<div class="directory-map"><div>${regionMap()}<span>권역별 탐색용 개략도 · 축척 없음</span></div><div><div class="eyebrow">PLACE, CLIMATE & CULTURE</div><h2>지역을 고르면,<br>그곳의 건축만 만납니다.</h2><p>지도의 이름이나 아래의 지역 카드를 눌러 보세요. 지역의 이야기와 건축 목록이 별도 페이지로 열립니다.</p><p class="scope-note">같은 지역 안에서도 시대·환경·계층에 따른 차이가 있습니다. 대표 사례를 지역 전체의 단일 양식으로 일반화하지 않습니다.</p></div></div>`:''}${['functions','types'].includes(route.dimension)?`<div class="classification-note">${icon('info')}<p><strong>${route.dimension==='functions'?'기능은 건축의 쓰임을 뜻합니다.':'종류는 건축물과 공간의 형태를 뜻합니다.'}</strong> ${route.dimension==='functions'?'예를 들어, 한옥과 아파트는 종류가 달라도 주거 기능을 공유합니다. 한 기록이 여러 기능에 포함될 수 있습니다.':'예를 들어, 사찰과 궁궐은 목재를 사용하더라도 종류와 목적이 다릅니다. 학습을 돕기 위한 편집 분류입니다.'}</p><a href="/${route.dimension==='functions'?'types':'functions'}/">${route.dimension==='functions'?'종류별':'기능별'}로 탐색 ${icon('arrow')}</a></div>`:''}<div class="directory-section-heading"><h2>${route.dimension==='periods'?'시간의 흐름':route.dimension==='regions'?'대한민국의 6개 권역':route.dimension==='functions'?'건축의 일곱 가지 쓰임':'건축의 열두 가지 종류'}</h2><span>유형 선택 → 기록 목록 → 건축 상세</span></div><div class="category-grid ${route.dimension==='periods'?'period-grid':''}">${regular.map((c,i)=>categoryCard(route.dimension,c,i)).join('')}</div>${extra.length?`<section class="supplemental"><h2>한국 건축사의 연결된 지역</h2><p>현재의 대한민국 행정구역 밖과 여러 지역에 걸친 사례도 맥락을 함께 읽습니다.</p><div class="category-grid">${extra.map((c,i)=>categoryCard(route.dimension,c,regular.length+i)).join('')}</div></section>`:''}</div>`;}

function collectionSidebar(route){const d=dimensions[route.dimension];return `<aside class="collection-sidebar"><a class="sidebar-back" href="/${route.dimension}/">${icon('layers')} ${d.name}</a><nav aria-label="${d.name}의 하위 유형">${d.categories.map(c=>`<a href="${categoryURL(route.dimension,c.id)}" class="${c.id===route.id?'active':''}" ${c.id===route.id?'aria-current="page"':''}><span>${esc(c.name)}</span><small>${recordsFor(route.dimension,c.id).length}</small></a>`).join('')}</nav><div class="sidebar-cross"><span>다른 관점으로 보기</span>${Object.entries(dimensions).filter(([id])=>id!==route.dimension).map(([id,x])=>`<a href="/${id}/">${x.name} ${icon('arrow')}</a>`).join('')}</div></aside>`;}
export function collectionListing(route,query=''){const params=paramsOf(query);const all=recordsFor(route.dimension,route.id);let list=all;const q=(params.get('q')||'').trim().toLowerCase();const era=params.get('era')||'';const use=params.get('function')||'';const sort=params.get('sort')||'time';if(q)list=list.filter(b=>`${b.title} ${b.location} ${b.summary} ${b.material} ${b.structure}`.toLowerCase().includes(q));if(era)list=list.filter(b=>b.era===era);if(use)list=list.filter(b=>classification[b.id].functions.includes(use));if(sort==='name')list=[...list].sort((a,b)=>a.title.localeCompare(b.title,'ko'));const totalPages=Math.max(1,Math.ceil(list.length/PAGE_SIZE));const requested=Number(params.get('page'));const page=Number.isSafeInteger(requested)&&requested>0?Math.min(requested,totalPages):1;const pageURL=n=>{const next=new URLSearchParams(params);next.set('page',String(n));return categoryURL(route.dimension,route.id)+'?'+esc(next.toString());};const selected=(a,b)=>a===b?'selected':'';
 return `<form class="listing-form" action="${categoryURL(route.dimension,route.id)}" method="get"><label class="list-search">${icon('search')}<input type="search" name="q" value="${esc(params.get('q')||'')}" placeholder="이 유형 안에서 검색" aria-label="이 유형 안에서 검색"></label>${route.dimension!=='periods'?`<label><span class="sr-only">시대 선택</span><select name="era" aria-label="시대 선택"><option value="">모든 시대</option>${periodCategories.map(e=>`<option value="${e.id}" ${selected(e.id,era)}>${e.name}</option>`).join('')}</select></label>`:`<label><span class="sr-only">기능 선택</span><select name="function" aria-label="기능 선택"><option value="">모든 기능</option>${functions.map(f=>`<option value="${f.id}" ${selected(f.id,use)}>${f.name}</option>`).join('')}</select></label>`}<label><span class="sr-only">정렬 방식</span><select name="sort" aria-label="정렬 방식"><option value="time" ${selected(sort,'time')}>시대순</option><option value="name" ${selected(sort,'name')}>이름순</option></select></label><button class="button dark" type="submit">적용</button></form><div class="listing-meta"><span>총 <strong>${list.length}</strong>개 기록${list.length!==all.length?` <span class="subtle">/ 이 유형 전체 ${all.length}개</span>`:''}</span><span>${list.length?`${(page-1)*PAGE_SIZE+1}–${Math.min(page*PAGE_SIZE,list.length)}`:'0'} / ${list.length}${q||era||use?` · <a href="${categoryURL(route.dimension,route.id)}">조건 초기화</a>`:''}</span></div><div class="cards-grid collection-grid">${list.length?cards(list.slice((page-1)*PAGE_SIZE,page*PAGE_SIZE)):empty(undefined,undefined,categoryURL(route.dimension,route.id))}</div>${totalPages>1?`<nav class="pagination" aria-label="목록 페이지">${page>1?`<a href="${pageURL(page-1)}" aria-label="이전 페이지">←</a>`:''}${Array.from({length:totalPages},(_,i)=>`<a href="${pageURL(i+1)}" ${i+1===page?'aria-current="page"':''}>${i+1}</a>`).join('')}${page<totalPages?`<a href="${pageURL(page+1)}" aria-label="다음 페이지">→</a>`:''}</nav>`:''}`;
}
function collection(route,query){const d=dimensions[route.dimension],c=categoryOf(route.dimension,route.id),list=recordsFor(route.dimension,route.id);return `<div class="wrap page-content">${breadcrumb([[d.name,`/${route.dimension}/`],[c.name]])}<div class="collection-layout"><div class="collection-main"><div class="collection-heading"><div><div class="eyebrow">${d.en}</div><h1>${esc(c.name)}</h1><span>${esc(c.subtitle||c.date||c.title||'')}</span></div><span class="collection-heading-icon">${icon(d.icon)}</span></div><p class="collection-description">${esc(c.desc)}</p>${c.keywords||c.tags?`<div class="keyword-list">${(c.keywords||c.tags).map(k=>`<span># ${k}</span>`).join('')}</div>`:''}<div id="collection-listing">${collectionListing(route,query)}</div><div class="collection-footnote"><strong>출처를 따라 더 깊이 읽기</strong>${(c.source||sourcesFor(list)).slice(0,4).map(id=>sourceLink(id)).join('')}<p>기능·종류는 학습을 돕는 편집 분류입니다. 복원·중건 여부와 해석의 범위는 각 상세 기록에서 확인하세요.</p></div></div></div></div>`;}

function record(route){const b=byId(route.id),c=classification[b.id],type=categoryOf('types',c.type),related=recordsFor('types',c.type).filter(x=>x.id!==b.id).slice(0,3);return `<div class="wrap page-content record-page">${breadcrumb([['종류별 탐색','/types/'],[type.name,categoryURL('types',type.id)],[b.title]])}<div class="record-topline"><a class="text-link" href="${categoryURL('types',type.id)}">← ${type.name} 목록</a><div class="record-actions">${saveButton(b,true)}<a class="button dark" href="/compare/?left=${b.id}&right=${b.id==='ddp'?'hahoe':'ddp'}">${icon('compare')} 이 건축 비교</a></div></div><div class="record-title"><div class="eyebrow">${eraOf(b.era).name} · ${esc(b.location)}</div><h1>${esc(b.title)}</h1><p>${esc(b.summary)}</p></div><div class="record-layout"><article class="record-article"><figure class="record-photo">${media(b,'record-image',false)}<figcaption>${esc(b.imageLabel||'현존 모습의 기록 사진 · 창건 당시의 원형 사진과 구분해 읽습니다.')} <a href="/library/photos/">사진 이용 안내 ↗</a></figcaption></figure><section class="record-section"><h2>건축의 구조와 삶</h2><dl class="detail-facts">${[['date','시기·연대'],['material','주요 재료'],['structure','구조·형태'],['space','공간 구성'],['culture','문화와 생활']].map(([key,label])=>`<div><dt>${label}</dt><dd>${esc(b[key])}</dd></div>`).join('')}</dl><div class="detail-point"><strong>${icon('bulb')} 이렇게 관찰해 보세요</strong><p>${esc(b.point)}</p></div><p class="detail-caution">${esc(b.caution)}</p></section><section class="record-section"><h2>원자료로 더 읽기</h2><div class="record-source-list">${b.sources.map(id=>sourceLink(id)).join('')}</div></section><section class="record-section note-section"><h2>나의 관찰 메모</h2><label class="sr-only" for="learning-note">나의 관찰 메모</label><textarea id="learning-note" maxlength="3000" placeholder="새롭게 알게 된 점이나 다른 건축과 비교할 점을 남겨 보세요."></textarea><div class="note-toolbar"><span id="note-status">보관함과 메모는 이 브라우저에 저장됩니다.</span><button class="button" data-action="save-note" data-id="${b.id}">메모 저장</button></div></section></article><aside class="record-sidebar"><div class="record-index"><h2>이 건축의 다른 관점</h2><div><span>시대</span><a href="${categoryURL('periods',b.era)}">${eraOf(b.era).name} ${icon('arrow')}</a></div><div><span>지역</span>${(c.regions||[b.region]).map(id=>`<a href="${categoryURL('regions',id)}">${categoryOf('regions',id).name} ${icon('arrow')}</a>`).join('')}</div><div><span>기능 · 쓰임</span>${c.functions.map(id=>`<a href="${categoryURL('functions',id)}">${categoryOf('functions',id).name} ${icon('arrow')}</a>`).join('')}</div><div><span>종류 · 형태</span><a href="${categoryURL('types',c.type)}">${type.name} ${icon('arrow')}</a></div><p>같은 기록을 여러 관점으로 이어 읽을 수 있습니다.</p></div></aside></div>${related.length?`<section class="record-related"><div class="section-head"><h2>같은 종류의 다른 공간</h2><a class="text-link" href="${categoryURL('types',type.id)}">${type.name} 목록 ${icon('arrow')}</a></div><div class="cards-grid">${cards(related)}</div></section>`:''}</div>`;}

function compareSelector(b,side){return `<div class="compare-selector"><label for="${side}-era">시대<select id="${side}-era" data-select="compare-era" data-side="${side}">${periodCategories.map(e=>`<option value="${e.id}" ${e.id===b.era?'selected':''}>${e.name}</option>`).join('')}</select></label><label for="${side}-building">건축 기록<select id="${side}-building" data-select="compare-building" data-side="${side}">${buildings.filter(x=>x.era===b.era).map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label></div>`;}
export function compareContent(leftId='hahoe',rightId='mapo'){const left=byId(leftId)||byId('hahoe'),right=byId(rightId)||byId('mapo');const same=['station','reuse'].includes(left.id)&&['station','reuse'].includes(right.id);return `<div class="compare-presets">${[['hahoe','mapo','한옥과 아파트'],['buseok','ddp','목구조와 비정형 건축'],['station','reuse','한 건물, 달라진 쓰임'],['amsa','hahoe','움집에서 한옥으로']].map(([l,r,t])=>`<a href="/compare/?left=${l}&right=${r}" class="preset-link">${t}</a>`).join('')}<button class="print-button text-link" data-action="print">${icon('print')} 비교 내용 인쇄</button></div><div class="comparison-panels">${[[left,'left'],[right,'right']].map(([b,side])=>`<section class="comparison-panel">${compareSelector(b,side)}${media(b,'comparison-photo',false)}<div class="comparison-caption">${esc(b.imageLabel||'현존 모습의 기록 사진 · 해당 시대 원형을 확정하는 사진은 아닙니다.')}</div><div class="comparison-heading"><div class="eyebrow">${eraOf(b.era).name} · ${esc(b.date)}</div><h2>${esc(b.title)}</h2><p>${esc(b.summary)}</p><a class="text-link compare-detail" href="${recordURL(b.id)}">상세 페이지에서 읽기 ${icon('arrow')}</a></div></section>`).join('')}</div><div class="comparison-table" role="table" aria-label="두 건축의 특성 비교"><div class="comparison-row head" role="row"><strong role="columnheader">비교 기준</strong><p role="columnheader">${esc(left.title)}</p><p role="columnheader">${esc(right.title)}</p></div>${[['material','재료','layers'],['structure','구조·형태','building'],['space','공간 구성','compare'],['culture','문화·생활','book'],['point','관찰 포인트','bulb']].map(([k,label,ico])=>`<div class="comparison-row" role="row"><strong role="rowheader">${icon(ico)}${label}</strong><p role="cell">${esc(left[k])}</p><p role="cell">${esc(right[k])}</p></div>`).join('')}</div><div class="comparison-takeaway">${icon('bulb')}<div><h3>차이를 발견했다면, 그 이유도 생각해 보세요.</h3><p>${left.id===right.id?'동일한 기록을 선택했습니다. 다른 건축을 선택하면 차이를 살펴볼 수 있습니다.':same?'같은 건물도 새로운 공공공간으로 다시 쓰일 수 있습니다. 형태의 보존과 기능의 변화를 분리해서 읽어 보세요.':'두 사례의 차이는 시대뿐 아니라 기능과 지역에서도 비롯됩니다. 건축의 재료·구조와 그 안에서 이루어진 활동을 함께 비교해 보세요.'}</p></div></div><div class="comparison-sources"><span>비교에 사용한 근거 자료</span>${sourcesFor([left,right]).map(id=>sourceLink(id)).join('')}</div>`;}
function compare(query){const p=paramsOf(query);return `<div class="wrap page-content">${breadcrumb([['건축 비교']])}${intro('THEN, NOW & IN BETWEEN','두 공간을 나란히, 더 깊이 이해하기','시대와 건축 기록을 선택해 같은 기준으로 비교하세요. 선택한 비교 주소를 복사해 다시 열 수도 있습니다.')}<div id="compare-content">${compareContent(p.get('left')||'hahoe',p.get('right')||'mapo')}</div></div>`;}

function libraryNavigation(active){return `<nav class="library-page-nav" aria-label="자료실 메뉴">${[['/library/','출처 자료','sources'],['/library/glossary/','건축 용어집','glossary'],['/library/quiz/','배움 확인','quiz'],['/library/photos/','사진 출처','credits']].map(([url,label,id])=>`<a href="${url}" class="${id===active?'active':''}" ${id===active?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;}
export function sourcesContent(query=''){const p=paramsOf(query),q=(p.get('q')||'').trim().toLowerCase(),kind=p.get('kind')||'';const list=sources.filter(s=>(!kind||s.kind===kind)&&(!q||`${s.title} ${s.org} ${s.note}`.toLowerCase().includes(q)));return `<form class="listing-form source-filter-form" action="/library/" method="get"><label class="list-search">${icon('search')}<input type="search" name="q" value="${esc(p.get('q')||'')}" placeholder="기관명, 자료명 검색" aria-label="기관명, 자료명 검색"></label><label><span class="sr-only">자료 분류</span><select name="kind" aria-label="자료 분류"><option value="">모든 자료</option>${['박물관','국가유산','세계유산','연구·사전','공공기관'].map(k=>`<option value="${k}" ${kind===k?'selected':''}>${k}</option>`).join('')}</select></label><button class="button dark" type="submit">검색</button></form><div class="listing-meta"><span>원자료 <strong>${list.length}</strong>개</span>${q||kind?'<a href="/library/">전체 자료</a>':''}</div><div class="source-grid">${list.length?list.map(s=>`<article class="source-card"><div class="source-type">${icon(s.kind==='박물관'?'building':'book')}${s.kind}</div><h3>${esc(s.title)}</h3><div class="org">${esc(s.org)}</div><p>${esc(s.note)}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">원자료 읽기 ${icon('external')}</a></article>`).join(''):empty('일치하는 자료가 없습니다.','검색어나 자료 분류를 바꿔 보세요.','/library/')}</div>`;}
export function quizContent(index=0,answers=[]){if(index>=questions.length){const score=answers.filter((a,i)=>a===questions[i].answer).length;return `<div class="quiz-wrap quiz-complete">${icon('check')}<div class="eyebrow">A LITTLE MORE KNOWLEDGE</div><h2>건축을 보는 눈이 한 뼘 더.</h2><p>${questions.length}문제 중 ${score}문제를 맞혔습니다.</p><button class="button primary" data-action="quiz-restart">다시 풀어보기</button> <a class="button" href="/periods/">시대별로 읽기 ${icon('arrow')}</a></div>`;}const q=questions[index],answered=answers[index]!==undefined;return `<div class="quiz-wrap"><div class="quiz-progress"><span>건축 읽기 · 작은 확인</span><span>${index+1} / ${questions.length}</span></div><div class="progress-track"><span style="width:${index/questions.length*100}%"></span></div><h2>${q.q}</h2>${q.options.map((o,i)=>`<button class="quiz-option ${answered?(i===q.answer?'correct':i===answers[index]?'incorrect':''):''}" data-action="quiz-answer" data-id="${i}" ${answered?'disabled':''}><span>${i+1}</span>${o}</button>`).join('')}${answered?`<div class="quiz-answer"><strong>${answers[index]===q.answer?'맞았습니다.':'함께 다시 살펴볼까요?'}</strong><p>${q.why}</p></div><div class="quiz-next"><button class="button primary" data-action="quiz-next">${index===questions.length-1?'결과 보기':'다음 질문'} ${icon('arrow')}</button></div>`:'<p class="subtle">답을 고르면 해설을 확인할 수 있습니다.</p>'}</div>`;}
function library(route,query,credits){let title='',desc='',body='';if(route.kind==='sources'){title='건축을 읽는 바탕, 출처 자료';desc='박물관과 공공기관의 원자료를 기관·분류별로 찾아 읽습니다.';body=`<div class="method-note"><h2>자료를 읽는 기준</h2><p>공개 자료를 요약·재구성한 대표 사례 중심의 학습용 아카이브입니다. 선사 주거의 추정과 발굴 흔적, 건물의 창건·중수·재건을 구분합니다. 기능과 종류는 학습을 위한 편집 분류이며, 분류가 역사적 양식을 확정하는 것은 아닙니다. 자료 확인: 2026.10.26.</p></div><div id="sources-content">${sourcesContent(query)}</div>`;}else if(route.kind==='glossary'){title='건축을 읽는 작은 사전';desc='용어를 익히고, 기록의 사진과 구조에서 직접 찾아보세요.';body=`<div class="glossary-grid">${glossary.map(([term,desc,id])=>`<article class="glossary-card"><h2>${term}</h2><p>${desc}</p>${sourceLink(id)}</article>`).join('')}</div>`;}else if(route.kind==='quiz'){title='배운 내용을, 한 번 더';desc='짧은 질문과 해설로 건축 기록을 읽는 기준을 확인합니다.';body=`<div id="quiz-content">${quizContent()}</div>`;}else{title='사진 출처와 이용 안내';desc='각 사진의 저작자와 공개 라이선스, 원본 파일을 확인할 수 있습니다.';body=`<div class="method-note"><h2>사진과 개념도를 구분해 읽습니다.</h2><p>사진은 Wikimedia Commons의 공개 라이선스 파일을 사용하고 화면에 맞게 잘라 표시합니다. 개념도는 직접 제작한 설명용 도식이며 특정 유적의 실측도나 학술 복원도가 아닙니다.</p></div><div class="photo-credit-grid">${credits.map(c=>`<article class="photo-credit-card"><img src="/assets/${c.id}.jpg" alt="${esc(c.name)}" loading="lazy"><div><h2>${esc(c.name)}</h2><p>저작자: ${esc(c.artist)}</p><p>${c.licenseUrl?`<a href="${esc(c.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(c.license)} ↗</a>`:esc(c.license)}</p><a class="text-link" href="${esc(c.source)}" target="_blank" rel="noopener noreferrer">원본 파일 ${icon('external')}</a></div></article>`).join('')}</div>`;}return `<div class="wrap page-content">${breadcrumb([['자료실',route.kind==='sources'?undefined:'/library/'],...(route.kind==='sources'?[]:[[route.kind==='glossary'?'건축 용어집':route.kind==='quiz'?'배움 확인':'사진 출처']])])}${intro('SOURCES & LEARNING',title,desc)}${libraryNavigation(route.kind)}${body}</div>`;}

export function savedContent(ids=[]){const list=ids.map(byId).filter(Boolean);return `<div class="listing-meta"><span>보관한 기록 <strong>${list.length}</strong>개</span></div><div class="cards-grid saved-grid">${list.length?cards(list):`<div class="empty">${icon('bookmark')}<h2>기억하고 싶은 공간을 담아 보세요.</h2><p>건축 기록의 책갈피를 누르면 이 페이지에 모입니다.</p><a class="button primary" href="/types/">종류별로 둘러보기 ${icon('arrow')}</a></div>`}</div>`;}
function saved(){return `<div class="wrap page-content">${breadcrumb([['나의 보관함']])}${intro('MY ARCHITECTURE COLLECTION','다시 읽고 싶은 공간들','보관함과 각 기록의 관찰 메모는 이 브라우저에 저장됩니다.')}<div id="saved-content">${savedContent()}</div></div>`;}
export function searchContent(query=''){const p=paramsOf(query),q=(p.get('q')||'').toLowerCase().trim();const list=q?buildings.filter(b=>`${b.title} ${b.location} ${eraOf(b.era).name} ${b.summary} ${b.material} ${b.structure} ${b.culture} ${categoryOf('types',classification[b.id].type).name} ${classification[b.id].functions.map(id=>categoryOf('functions',id).name).join(' ')}`.toLowerCase().includes(q)):[];return !q?`<div class="search-start">${icon('search')}<h2>어떤 공간이 궁금한가요?</h2><p>건축 이름뿐 아니라 ‘주심포’, ‘제주’, ‘온돌’로도 찾아보세요.</p><div class="suggested-searches">${['주심포','제주','온돌','아파트'].map(x=>`<a href="/search/?q=${encodeURIComponent(x)}">${x} ${icon('arrow')}</a>`).join('')}</div></div>`:`<div class="listing-meta"><span>‘${esc(p.get('q'))}’ 검색 결과 <strong>${list.length}</strong>개</span></div><div class="cards-grid search-grid">${list.length?cards(list):empty('검색 결과가 없습니다.','다른 단어나 건축 이름으로 찾아보세요.')}</div>`;}
function search(query){const p=paramsOf(query);return `<div class="wrap page-content">${breadcrumb([['아카이브 검색']])}${intro('FIND A SPACE','궁금한 공간을 찾아보세요','건축 이름, 시대, 지역, 재료와 구조 용어로 기록을 검색합니다.')}<form class="page-search-form" action="/search/" method="get">${icon('search')}<label class="sr-only" for="search-query">아카이브 검색어</label><input id="search-query" type="search" name="q" placeholder="건축 이름, 시대, 지역, 용어 검색" value="${esc(p.get('q')||'')}"><button class="button primary" type="submit">검색 ${icon('arrow')}</button></form><div id="search-content">${searchContent(query)}</div></div>`;}
function notfound(){return `<div class="wrap page-content">${intro('404 · A DIFFERENT PATH','이 페이지를 찾을 수 없습니다.','메뉴에서 새로운 탐색을 시작하거나 건축 이름으로 검색해 보세요.')}<div class="notfound-links"><a class="button primary" href="/">홈으로 ${icon('arrow')}</a><a class="button" href="/search/">아카이브 검색</a></div></div>`;}
export function renderPage(route,query='',credits=[]){if(route.kind==='home')return home();if(route.kind==='directory')return directory(route);if(route.kind==='collection')return collection(route,query);if(route.kind==='record')return record(route);if(route.kind==='compare')return compare(query);if(['sources','glossary','quiz','credits'].includes(route.kind))return library(route,query,credits);if(route.kind==='saved')return saved();if(route.kind==='search')return search(query);return notfound();}
